{
  "headline": "FDA's shortage list shows bumetanide injection from multiple manufacturers with resolved status since 2017-12-13; Hikma's registered plant has only VAI inspections and a recent NAI inspection on 2026-05-13",
  "headline_cites": ["E29", "E25", "E17"],
  "sentences": [
    {
      "text": "FDA first posted the bumetanide injection shortage on 2017-12-13 and as of 2026-10-21 it has been on the list for 106 months.",
      "cites": ["E29", "D8"]
    },
    {
      "text": "The shortage entries for Hikma Pharmaceuticals USA Inc., Sagent Pharmaceuticals, Fresenius Kabi USA LLC, MSN Laboratories Private Limited, and Mullan Pharmaceutical Inc. all show resolved status with an update date of 2026-09-30.",
      "cites": ["E25", "E28", "E24", "E26", "E27"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. is a registered plant (FEI 2220525) for bumetanide 0.25 mg/mL with operations including manufacture, analysis, and labeling.",
      "cites": ["E17"]
    },
    {
      "text": "FDA inspections of Hikma's plant from 2009 through 2024 have all been classified VAI, with the most recent inspection ending 2024-06-12 and a known date of 2024-12-16.",
      "cites": ["E10", "E11", "E12", "E13", "E14", "E15", "E16"]
    },
    {
      "text": "The plant's last inspection was NAI on 2026-05-13, indicating no action indicated at that time.",
      "cites": ["E17"]
    },
    {
      "text": "P&T has approved interchange to Hikma's bumetanide 0.25 mg/mL (NDC 00641600710) as a same product, alternate manufacturer option approved by Sam Rivera, MD on 2026-07-01.",
      "cites": ["E30", "D5"]
    },
    {
      "text": "Corvale East and Corvale General each have approximately 19 days of bumetanide supply on hand at current usage rates.",
      "cites": ["D1", "D2"]
    }
  ]
}
